import csv
from datetime import datetime
import hashlib
import io
from pathlib import Path
import sqlite3
import tempfile
import unittest
from unittest.mock import patch

import config
import database
import training_history


NOW = datetime(2026, 11, 15, 10)


def source_row(**changes):
    """Return a synthetic source record in the exact supplied CSV column order."""
    row = {'Sports': 'Yoga', 'Sportart': 'Alle Level', 'Tag': 'Wednesday', 'Zeit': '08:00',
           'Termin': 'Mittwoch, 4. November 2026', 'Teilnehmer signed up': '0',
           'Teilnehmer teacher': '12', 'Max participants': '9999'}
    row.update(changes)
    return [row[name] for name in config.TRAINING_CSV_HEADERS]


def csv_bytes(rows, headers=None):
    """Encode small semicolon-separated fixtures, preserving quoting and Unicode exactly."""
    stream = io.StringIO(newline='')
    writer = csv.writer(stream, delimiter=';', lineterminator='\r\n')
    writer.writerow(config.TRAINING_CSV_HEADERS if headers is None else headers)
    writer.writerows(rows)
    return stream.getvalue().encode('utf-8-sig')


class TrainingHistoryTests(unittest.TestCase):
    """Protect archive identity, original multiplicities and all-or-nothing transactions."""

    def setUp(self):
        """Use only a disposable source directory and a new in-memory project database."""
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.directory = Path(temporary.name)
        self.connection = database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        database.init_db(self.connection)

    def write_csv(self, rows=None, name='training.csv', headers=None):
        """Create one test source without using or copying uploaded personal records."""
        path = self.directory / name
        path.write_bytes(csv_bytes([source_row()] if rows is None else rows, headers))
        return path

    def load(self, path):
        """Run the public importer with an injected clock for reproducible provenance."""
        return training_history.import_training_csv(self.connection, path, now=NOW)

    def archive_rows(self):
        """Read all persisted archive values with stable IDs and original line references."""
        return [tuple(row) for row in self.connection.execute(
            'SELECT * FROM training_history ORDER BY id').fetchall()]

    def scalar(self, query, params=()):
        """Read one value using fixed fixture SQL and bound parameters."""
        return self.connection.execute(query, params).fetchone()[0]

    def test_read_preserves_unicode_quoted_text_and_original_date(self):
        """Parse the German date explicitly while retaining exact original text fields."""
        row = source_row(Sports='Körpertraining', Sportart='Level "A"; freie Wahl')
        path = self.write_csv([row])
        result = training_history.read_training_csv(path)
        self.assertEqual(result['file_name'], path.name)
        fingerprint = hashlib.sha256(path.read_bytes()).hexdigest()
        self.assertEqual(result['source_fingerprint'], fingerprint)
        self.assertEqual(result['records'], [
            (2, 'Körpertraining', 'Level "A"; freie Wahl', 'Wednesday', '08:00',
             'Mittwoch, 4. November 2026', '2026-11-04', 0, 12, 9999)])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 0)

    def test_missing_values_and_zero_are_distinct(self):
        """Keep missing fields as NULL and preserve actual zero and sentinel-looking counts."""
        row = source_row(Sports='', Sportart='', **{'Teilnehmer signed up': '',
                                                   'Teilnehmer teacher': '0'})
        path = self.write_csv([row])
        self.load(path)
        stored = self.connection.execute('SELECT * FROM training_history').fetchone()
        self.assertIsNone(stored['sport'])
        self.assertIsNone(stored['variant'])
        self.assertIsNone(stored['participants_signed_up'])
        self.assertEqual(stored['participants_teacher'], 0)
        self.assertEqual(stored['max_participants'], 9999)

    def test_literal_na_text_is_not_treated_as_missing(self):
        """Do not let pandas' default missing-value vocabulary erase legitimate text."""
        path = self.write_csv([source_row(Sports='NA', Sportart='NULL')])
        row = training_history.read_training_csv(path)['records'][0]
        self.assertEqual(row[1:3], ('NA', 'NULL'))

    def test_duplicate_rows_and_nameless_rows_are_retained(self):
        """Keep repeated training observations as separate original source lines."""
        rows = [source_row(), source_row(), source_row(Sports='', Sportart='')]
        report = self.load(self.write_csv(rows))
        self.assertEqual(report['n_rows'], 3)
        self.assertEqual(report['n_imported'], 3)
        self.assertEqual(report['n_duplicate_rows'], 1)
        self.assertEqual(report['n_unnamed_rows'], 1)
        self.assertFalse(report['already_imported'])
        self.assertEqual(report['first_date'], '2026-11-04')
        self.assertEqual(report['last_date'], '2026-11-04')
        numbers = self.connection.execute(
            'SELECT source_row FROM training_history ORDER BY source_row').fetchall()
        self.assertEqual([row[0] for row in numbers], [2, 3, 4])

    def test_reimport_renamed_same_content_preserves_ids_and_provenance(self):
        """Recognize file contents rather than filename and leave the first import untouched."""
        path = self.write_csv([source_row(), source_row()])
        first = self.load(path)
        original_rows = self.archive_rows()
        original_import = tuple(self.connection.execute(
            'SELECT * FROM training_imports').fetchone())
        renamed = self.directory / 'renamed.csv'
        renamed.write_bytes(path.read_bytes())
        later = training_history.import_training_csv(
            self.connection, renamed, now=datetime(2026, 11, 16, 12))
        self.assertEqual(later['import_id'], first['import_id'])
        self.assertEqual(later['n_imported'], 0)
        self.assertTrue(later['already_imported'])
        self.assertEqual(self.archive_rows(), original_rows)
        self.assertEqual(tuple(self.connection.execute(
            'SELECT * FROM training_imports').fetchone()), original_import)

    def test_changed_contents_are_a_new_batch(self):
        """Retain both file versions when source data change under the same filename."""
        path = self.write_csv()
        first = self.load(path)
        path.write_bytes(csv_bytes([source_row(**{'Teilnehmer teacher': '13'})]))
        second = self.load(path)
        self.assertNotEqual(first['import_id'], second['import_id'])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 2)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 2)

    def test_csv_can_exceed_ordinary_live_import_limit(self):
        """Accept 5,001 historical rows without altering the ordinary event-source limit."""
        self.assertEqual(config.MAX_RECORDS_PER_SOURCE, 5000)
        report = self.load(self.write_csv([source_row()] * 5001))
        self.assertEqual(report['n_rows'], 5001)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 5001)
        self.assertEqual(config.MAX_RECORDS_PER_SOURCE, 5000)

    def test_header_only_and_empty_files_are_rejected(self):
        """Reject a source with no training rows and leave both archive tables empty."""
        path = self.write_csv([])
        for body in (path.read_bytes(), b'', b'\xef\xbb\xbf'):
            with self.subTest(size=len(body)):
                path.write_bytes(body)
                with self.assertRaises(ValueError):
                    self.load(path)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 0)

    def test_wrong_missing_extra_and_duplicate_headers_are_rejected(self):
        """Validate all eight column names before any archive write."""
        headers = list(config.TRAINING_CSV_HEADERS)
        cases = [headers[:-1], headers + ['Extra'], ['Wrong'] + headers[1:],
                 [headers[1]] + headers[1:]]
        for names in cases:
            with self.subTest(columns=names):
                path = self.write_csv([source_row()], headers=names)
                with self.assertRaises(ValueError):
                    self.load(path)
        path.write_bytes(csv_bytes([source_row()]).replace(b';', b','))
        with self.assertRaises(ValueError):
            self.load(path)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 0)

    def test_ragged_and_blank_rows_are_not_silently_ignored(self):
        """Reject extra, missing and blank records instead of truncating or skipping data."""
        for invalid in [source_row()[:-1], source_row() + ['PRIVATE_EXTRA'], []]:
            with self.subTest(fields=len(invalid)):
                path = self.write_csv([source_row(), invalid])
                with self.assertRaises(ValueError) as failure:
                    self.load(path)
                self.assertNotIn('PRIVATE_EXTRA', str(failure.exception))
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 0)

    def test_bad_encoding_is_rejected_without_exposing_contents(self):
        """Reject non-UTF-8 bytes rather than replacing invalid characters."""
        path = self.write_csv()
        path.write_bytes(path.read_bytes() + b'\xffPRIVATE_ENCODING')
        with self.assertRaises(ValueError) as failure:
            self.load(path)
        self.assertNotIn('PRIVATE_ENCODING', str(failure.exception))
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 0)

    def test_invalid_dates_weekdays_and_times_reject_the_whole_source(self):
        """Validate calendar meaning and both weekday representations before insertion."""
        changes = [{'Termin': 'Mittwoch, 31. Februar 2026'},
                   {'Termin': 'Mittwoch, 4. PRIVATE_MONTH 2026'},
                   {'Termin': 'Donnerstag, 4. November 2026'},
                   {'Termin': 'Samstag, 4. November 23', 'Tag': 'Saturday'},
                   {'Termin': '2026-11-04'}, {'Tag': 'Friday'},
                   {'Zeit': '24:00'}, {'Zeit': '08:60'}, {'Zeit': 'PRIVATE_TIME'}]
        for change in changes:
            with self.subTest(change=change):
                path = self.write_csv([source_row(), source_row(**change)])
                with self.assertRaises(ValueError) as failure:
                    self.load(path)
                self.assertNotIn('PRIVATE_', str(failure.exception))
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_history'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 0)

    def test_invalid_counts_are_rejected(self):
        """Reject negative, fractional, scientific and out-of-range participant counts."""
        invalid = ['-1', '1.5', '1,5', '1e3', '9223372036854775808',
                   'PRIVATE_COUNT', '9' * 5000]
        for value in invalid:
            for field in config.TRAINING_CSV_HEADERS[5:]:
                with self.subTest(field=field, value=value[:25]):
                    path = self.write_csv([source_row(**{field: value})])
                    with self.assertRaises(ValueError) as failure:
                        self.load(path)
                    self.assertNotIn('PRIVATE_COUNT', str(failure.exception))
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 0)

    def test_row_and_byte_caps_reject_without_partial_rows(self):
        """Enforce dedicated history bounds while keeping existing data intact."""
        self.load(self.write_csv())
        before = self.archive_rows()
        path = self.write_csv([source_row(), source_row()], name='other.csv')
        with patch.object(config, 'MAX_TRAINING_HISTORY_ROWS', 1):
            with self.assertRaises(ValueError):
                self.load(path)
        with patch.object(config, 'MAX_TRAINING_CSV_BYTES', 10):
            with self.assertRaises(ValueError):
                self.load(path)
        self.assertEqual(self.archive_rows(), before)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 1)

    def test_sql_like_text_is_stored_literally(self):
        """Bound SQL parameters preserve source text without interpreting it as a query."""
        title = "Yoga'); DROP TABLE events; --"
        self.load(self.write_csv([source_row(Sports=title)]))
        self.assertEqual(self.scalar('SELECT sport FROM training_history'), title)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 0)

    def test_database_error_rolls_back_all_rows_and_import_metadata(self):
        """Roll back a forced failure on the second row and preserve a previous batch."""
        self.load(self.write_csv())
        before = self.archive_rows()
        with self.connection:
            self.connection.executescript('''CREATE TRIGGER fail_second_history_row
                BEFORE INSERT ON training_history WHEN NEW.source_row=3
                BEGIN SELECT RAISE(ABORT, 'forced test failure'); END;''')
        path = self.write_csv([source_row(Sportart='New'), source_row()], name='other.csv')
        with self.assertRaises(sqlite3.Error):
            self.load(path)
        self.assertEqual(self.archive_rows(), before)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 1)
        self.assertFalse(self.connection.in_transaction)

    def test_pending_caller_transaction_is_not_committed(self):
        """Reject an already active transaction instead of committing unrelated writes."""
        path = self.write_csv()
        self.connection.execute('INSERT INTO app_settings(key,value) VALUES (?,?)',
                                ('pending_test', 'not committed'))
        with self.assertRaises(ValueError):
            self.load(path)
        self.assertTrue(self.connection.in_transaction)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 0)
        self.connection.rollback()
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM app_settings'), 0)

    def test_reimport_detects_missing_or_changed_archived_rows(self):
        """Do not call a damaged archive successful or silently repair it during reimport."""
        path = self.write_csv([source_row(), source_row()])
        self.load(path)
        for query in ['UPDATE training_history SET participants_teacher=999 WHERE source_row=2',
                      'DELETE FROM training_history WHERE source_row=3']:
            with self.connection:
                self.connection.execute(query)
            before = self.archive_rows()
            with self.assertRaises(ValueError):
                self.load(path)
            self.assertEqual(self.archive_rows(), before)
            if query.startswith('UPDATE'):
                with self.connection:
                    self.connection.execute(
                        'UPDATE training_history SET participants_teacher=12 WHERE source_row=2')

    def test_history_is_separate_from_events_and_survives_calendar_cleanup(self):
        """Archive old observations without creating public events or future predictions."""
        self.load(self.write_csv())
        before = self.archive_rows()
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM series'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 0)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 0)
        database.delete_past_unconfirmed_events(self.connection, datetime(2030, 1, 1))
        self.assertEqual(self.archive_rows(), before)
        database.reset_database(self.connection)
        self.assertEqual(self.archive_rows(), before)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM training_imports'), 1)
